mapper.insert:
INSERT INTO stock_data_system (stock_data_id, stock_system, freezer_category, freezer_position, price, active)
VALUES (#{dataId}, #{system}, #{category}, #{pos}, #{price}, #{active})
ON DUPLICATE KEY UPDATE
    id = id
, freezer_category = #{category}
, freezer_position = #{pos}
, price = #{price}
, active = #{active}

mapper.select:
SELECT s.price
FROM stock_data_system s
JOIN stock_data d ON d.id = s.stock_data_id
WHERE s.stock_system = #{system}
  AND s.price IS NOT NULL AND s.price > 0
  AND d.product_name = #{productName}

    AND d.product_code = #{codeNumber}

ORDER BY d.updated_at DESC, d.id DESC
LIMIT 1
